(function (global) {
  "use strict";

  /**
   * Newly generated Korean middle-school textbook style cartoon illustrations.
   * Stored as self-contained inline Data URLs so the entire app has zero external image file dependencies
   * and can be bundled into a single standalone HTML file at any time.
   */
  const CARD_DATA_URLS = {
    bread: "data:image/jpeg;base64,",
    salon: "data:image/jpeg;base64,",
    labor: "data:image/jpeg;base64,",
    land: "data:image/jpeg;base64,",
    capital: "data:image/jpeg;base64,"
  };

  function getCardIllustrationMarkup(scenarioId, altText) {
    const src = CARD_DATA_URLS[scenarioId] || "";
    const safeAlt = altText || "";
    return '<img class="card-illustration" src="' + src + '" alt="' + safeAlt + '" draggable="false" />';
  }

  global.CircularEconomyCardIllustrations = {
    CARD_DATA_URLS,
    getCardIllustrationMarkup
  };
})(window);